-- MT2009_PLUS_YOHARA_PB_V1: the elements of the awakened bosses' dungeons (setRaceFlag bits 11-16: 4096 fire, 8192
-- ice) as on the pl-wiki ("Zywiol": the fortress' monsters fire, the watchtower's ice; Owsap's AttFire / AttIce
-- agree). GENERATED by tools/yohara_pb/gen_ypb.py. apply.sh runs it AFTER zywioly_moby.sql, which clears bits 11-16
-- of every mob it does not list: idempotent, the end state is these bits.
SET NAMES utf8mb4;
-- ogien: 4300,4301,4302,4303,4304,4305,4306,4307,4308,4309,4411
UPDATE world.mob_proto SET setRaceFlag = ((setRaceFlag + 0) & ~129024) | 4096 WHERE vnum IN (4300,4301,4302,4303,4304,4305,4306,4307,4308,4309,4411);
-- lod: 4320,4321,4322,4323,4324,4325,4326,4327,4328,4329,4412
UPDATE world.mob_proto SET setRaceFlag = ((setRaceFlag + 0) & ~129024) | 8192 WHERE vnum IN (4320,4321,4322,4323,4324,4325,4326,4327,4328,4329,4412);
-- no element (the Metins and the pillar - the wiki gives a Metin none): 8134,8135,20538
UPDATE world.mob_proto SET setRaceFlag = (setRaceFlag + 0) & ~129024 WHERE vnum IN (8134,8135,20538) AND (setRaceFlag + 0) & 129024 <> 0;
